-- ----------------------------
-- Table structure for t_device_init_entry
-- ----------------------------
DROP TABLE IF EXISTS `t_device_init_entry`;
CREATE TABLE `t_device_init_entry`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `dev_type_id` int(11) NULL DEFAULT NULL COMMENT '设备种类id',
  `dev_model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备型号',
  `dev_model_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '型号名',
  `dev_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备名称',
  `spacing_width` json NULL COMMENT '狭缝宽度',
  `init_entry` json NULL COMMENT '初始化项',
  `filter_wavelengths` json NULL COMMENT '滤色片波长点',
  `min_wavelength` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最小波长',
  `max_wavelength` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最大波长',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备型号信息' ROW_FORMAT = DYNAMIC;

